class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        sort(nums.rbegin(), nums.rend());
        if (nums[0] > target) return false;
        int n = nums.size();
        vector<int> dp(1 << n, -1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask] == -1) continue;
            int rem = target - (dp[mask] % target);
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    if (nums[i] <= rem) {
                        dp[mask | (1 << i)] = dp[mask] + nums[i];
                    } else {
                        break;
                    }
                }
            }
        }
        return dp[(1 << n) - 1] == total;
    }
};

class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        Arrays.sort(nums);
        int n = nums.length;
        for (int i = 0; i < n / 2; i++) {
            int temp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = temp;
        }
        if (nums[0] > target) return false;
        int[] dp = new int[1 << n];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == -1) continue;
            int rem = target - (dp[mask] % target);
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    if (nums[i] <= rem) {
                        dp[mask | (1 << i)] = dp[mask] + nums[i];
                    } else {
                        break;
                    }
                }
            }
        }
        return dp[(1 << n) - 1] == total;
    }
}

var canPartitionKSubsets = function(nums, k) {
    const total = nums.reduce((a, b) => a + b, 0);
    if (total % k !== 0) return false;
    const target = total / k;
    nums.sort((a, b) => b - a);
    if (nums[0] > target) return false;
    const n = nums.length;
    const dp = new Array(1 << n).fill(-1);
    dp[0] = 0;
    for (let mask = 0; mask < (1 << n); mask++) {
        if (dp[mask] === -1) continue;
        const rem = target - (dp[mask] % target);
        for (let i = 0; i < n; i++) {
            if (!(mask & (1 << i))) {
                if (nums[i] <= rem) {
                    dp[mask | (1 << i)] = dp[mask] + nums[i];
                } else {
                    break;
                }
            }
        }
    }
    return dp[(1 << n) - 1] === total;
};
